    local curePetrification = resolver:resolve({
        actor = cockatriceOilUser,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = cockatriceOil.id,
        target = petrifiedVictim,
        contestedUseItem = false,
    })
    assertTrue(curePetrification.success, "cockatrice oil should be usable on petrified creatures")
    assertTrue(not petrifiedVictim.conditions.petrified,
        "cockatrice oil should permanently cure petrification")
    assertTrue(petrifiedVictim.malediction.active == false,
        "cockatrice oil should end the petrification curse record")
    assertTrue(petrifiedVictim.properties.fleshyStone,
        "cockatrice oil should mark touched stone as fleshy")
    assertTrue(hasValue(curePetrification.effects, "petrification_cured"),
        "cockatrice oil should report the petrification cure")

    local cockatriceWallOil = inventory.createItemFromTemplate("cockatrice_oil")
    local grossWall = inventory.createItem({
        name = "Stone Wall",
        size = 6,
        properties = { material = "stone" },
    })
    cockatriceOilUser.inventory:addItem(cockatriceWallOil, inventory.LOCATIONS.HANDS)
    local wallOilUse = resolver:resolve({
        actor = cockatriceOilUser,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = cockatriceWallOil.id,
        target = grossWall,
        contestedUseItem = false,
    })
    assertTrue(wallOilUse.success, "cockatrice oil should be usable on stone walls")
    assertTrue(grossWall.properties.fleshyStone and grossWall.properties.material == "flesh",
        "cockatrice oil should make stone walls fleshy and gross")
    assertTrue(not cockatriceOilUser.inventory:findItem(cockatriceWallOil.id),
        "cockatrice oil should be consumed")

    do
        local impOilUser = base_entity.createEntity({
            id = "pc_imp_oil_user",
            name = "Imp Oil User",
            isPC = true,
        })
        impOilUser.inventory = inventory.createInventory()
        local impOil = inventory.createItemFromTemplate("imp_oil")
        local stoneFloor = inventory.createItem({
            name = "Stone Floor",
            type = "floor",
            properties = { floor = true },
        })
        impOilUser.inventory:addItem(impOil, inventory.LOCATIONS.HANDS)
        local impOilUse = resolver:resolve({
            actor = impOilUser,
            card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
            type = action_resolver.ACTION_TYPES.USE_ITEM,
            itemId = impOil.id,
            target = stoneFloor,
            contestedUseItem = false,
            pouredOut = true,
        })
        assertTrue(impOilUse.success, "imp oil should be usable on surfaces")
        assertTrue(stoneFloor.properties.frictionless and stoneFloor.properties.utterlyFrictionless,
            "imp oil should make touched surfaces frictionless")
        assertTrue(stoneFloor.properties.slipperyPuddle and stoneFloor.slipperyPuddle.diameterFeet == 10,
            "imp oil poured out should make a ten-foot slippery puddle")
        assertTrue(not impOilUser.inventory:findItem(impOil.id), "imp oil should be consumed")
    end

    do
        local griffinOilUser = base_entity.createEntity({
            id = "pc_griffin_oil_user",
            name = "Griffin Oil User",
            isPC = true,
        })
        griffinOilUser.inventory = inventory.createInventory()
        local griffinOil = inventory.createItemFromTemplate("griffin_oil")
        local rustyHelm = inventory.createItem({
            name = "Rusted Helm",
            size = 1,
            properties = {
                rusted = true,
                minorFlaw = true,
                impurities = true,
                filth = true,
            },
        })
        griffinOilUser.inventory:addItem(griffinOil, inventory.LOCATIONS.HANDS)
        local cleanHelm = resolver:resolve({
            actor = griffinOilUser,
            card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
            type = action_resolver.ACTION_TYPES.USE_ITEM,
            itemId = griffinOil.id,
            target = rustyHelm,
            contestedUseItem = false,
        })
        assertTrue(cleanHelm.success, "griffin oil should be usable on filthy objects")
        assertTrue(rustyHelm.properties.cleaned and rustyHelm.properties.griffinOilClean,
            "griffin oil should mark the target as clean")
        assertTrue(not rustyHelm.properties.rusted and not rustyHelm.properties.filth,
            "griffin oil should remove rust and filth")
        assertTrue(not griffinOilUser.inventory:findItem(griffinOil.id), "griffin oil should be consumed")

        local bathOil = inventory.createItemFromTemplate("griffin_oil")
        local stinkingAdventurer = base_entity.createEntity({
            id = "pc_griffin_bath",
            name = "Stinking Adventurer",
            isPC = true,
        })
        stinkingAdventurer.inventory = inventory.createInventory()
        stinkingAdventurer.conditions.stressed = true
        stinkingAdventurer.conditions.imp_stink = true
        stinkingAdventurer.conditions.choking_stink = true
        stinkingAdventurer.impStink = { stressedUntilWashed = true }
        stinkingAdventurer.inventory:addItem(bathOil, inventory.LOCATIONS.HANDS)
        local bathUse = resolver:resolve({
            actor = stinkingAdventurer,
            card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
            type = action_resolver.ACTION_TYPES.USE_ITEM,
            itemId = bathOil.id,
            target = stinkingAdventurer,
            dungeonBath = true,
        })
        assertTrue(bathUse.success, "griffin oil should support an impromptu dungeon bath")
        assertTrue(not stinkingAdventurer.conditions.imp_stink and not stinkingAdventurer.impStink,
            "griffin oil bath should wash off Imp stink")
        assertTrue(not stinkingAdventurer.conditions.stressed,
            "washing off Imp stink should clear its stress rider")
        assertTrue(stinkingAdventurer.griffinOilBath, "griffin oil should record the dungeon bath")
    end

    local questOil = inventory.createItemFromTemplate("questing_beast_oil")
    local barkingDoor = inventory.createItem({ name = "Barking Door", size = 2, properties = {} })
    local meatgrinderDraws = {
        { category = watch_manager.MEATGRINDER.RANDOM_ENCOUNTER, description = "A monster finds the sound." },
        { category = watch_manager.MEATGRINDER.CURIOSITY, description = "A strange noise answers." },
    }
    local meatgrinderDrawCount = 0
    local questWatch = {
        drawMeatgrinder = function()
            meatgrinderDrawCount = meatgrinderDrawCount + 1
            return meatgrinderDraws[meatgrinderDrawCount]
        end,
    }
    actor.inventory:addItem(questOil, inventory.LOCATIONS.HANDS)
    local questOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = questOil.id,
        target = barkingDoor,
        watchManager = questWatch,
    })
    assertTrue(questOilUse.success, "questing beast oil should be usable on an object")
    assertEqual(meatgrinderDrawCount, 2,
        "questing beast oil should draw twice on the Meatgrinder table")
    assertTrue(barkingDoor.properties.barkingLure and barkingDoor.properties.questingBeastBark,
        "questing beast oil should mark a barking lure")
    assertEqual(barkingDoor.properties.effectDurations.barkingLure.duration, "watch",
        "questing beast oil should last for a watch")
    assertEqual(#questOilUse.questingBeastEncounters, 1,
        "questing beast oil should flag encounters drawn to the lure")
    assertTrue(meatgrinderDraws[1].questingBeastLure,
        "questing beast oil should annotate drawn encounter records")
    assertTrue(not actor.inventory:findItem(questOil.id), "questing beast oil should be consumed")

    local ungoatOil = inventory.createItemFromTemplate("ungoat_oil")
    local spellCaster = base_entity.createEntity({
        id = "pc_ungoat_oil_caster",
        name = "Ungoat Oil Caster",
        isPC = true,
        conditions = {},
    })
    local spellTarget = base_entity.createEntity({
        id = "pc_ungoat_oil_target",
        name = "Ungoat Oil Target",
        isPC = true,
        conditions = {},
    })
    local activeSizeSpell = {
        spellId = "change_size",
        target = spellTarget,
        resolveCommitted = 1,
        concentration = true,
    }
    spellCaster.activeSpells = { activeSizeSpell }
    spellCaster.committedResolve = 1
    spellTarget.conditions.sizeChanged = true
    spellTarget.conditions.sizeGrown = true
    spellTarget.changeSize = { caster = spellCaster, active = true, mode = "grow" }
    spellTarget.sizeMultiplier = 2
    actor.inventory:addItem(ungoatOil, inventory.LOCATIONS.HANDS)
    local ungoatOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = ungoatOil.id,
        target = spellTarget,
        allEntities = { spellCaster },
    })
    assertTrue(ungoatOilUse.success, "ungoat oil should be usable on a spell-affected target")
    assertEqual(#spellCaster.activeSpells, 0,
        "ungoat oil should end active concentration spells affecting the target")
    assertEqual(spellCaster.committedResolve, 0,
        "ungoat oil should release committed Resolve from ended concentration spells")
    assertTrue(spellTarget.changeSize == nil and not spellTarget.conditions.sizeChanged,
        "ungoat oil should run active spell cleanup")
    assertTrue(spellTarget.properties.magicSuppressed,
        "ungoat oil should suppress target magic for a watch")
    assertEqual(spellTarget.properties.effectDurations.magicSuppressed.duration, "watch",
        "ungoat oil suppression should record its watch duration")
    assertTrue(not actor.inventory:findItem(ungoatOil.id), "ungoat oil should be consumed")

    local slimeOil = inventory.createItemFromTemplate("slime_oil")
    local woodenDoor = inventory.createItem({
        name = "Wooden Door",
        size = 2,
        durability = 2,
        properties = { material = "wood" },
    })
    actor.inventory:addItem(slimeOil, inventory.LOCATIONS.HANDS)
    local slimeOilUse = resolver:resolve({
        actor = actor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = slimeOil.id,
        target = woodenDoor,
    })
    assertTrue(slimeOilUse.success, "slime oil should be usable on an object")
    assertTrue(woodenDoor.destroyed, "slime oil should destroy non-magical objects it touches")
    assertTrue(not actor.inventory:findItem(slimeOil.id), "slime oil should be consumed")

    local undeadActor = base_entity.createEntity({
        id = "undead_potion_user",
        name = "Undead",
        isPC = false,
        health = 2,
        defense = 0,
        undead = true,
    })
    undeadActor.undead = true
    undeadActor.inventory = inventory.createInventory()
    local undeadPotion = inventory.createItemFromTemplate("slime_potion")
    undeadActor.inventory:addItem(undeadPotion, inventory.LOCATIONS.HANDS)
    local undeadPotionUse = resolver:resolve({
        actor = undeadActor,
        card = { name = "Cups", value = 1, suit = constants.SUITS.CUPS },
        type = action_resolver.ACTION_TYPES.USE_ITEM,
        itemId = undeadPotion.id,
    })
    assertTrue(undeadPotionUse.success, "potion use on undead should still spend the item")
    assertTrue(not undeadActor.conditions.shapeless_body, "potions should not affect undead")
    assertTrue(not undeadActor.inventory:findItem(undeadPotion.id), "ineffective potion should still be consumed")
end

local function checkCampTinkersKitRepair()
    local actor = base_entity.createEntity({
        id = "pc_tinker",
        name = "Tinker",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()

    local kit = inventory.createItemFromTemplate("tinkers_kit")
    assertEqual(kit.size, 2, "tinker's kit should take two slots")
    actor.inventory:addItem(kit, inventory.LOCATIONS.PACK)

    local sword = inventory.createItem({
        name = "Notched Sword",
        size = 1,
        durability = 2,
    })
    sword.notches = 1

    local ok, result = camp_actions.resolveRepair(actor, sword, events.createEventBus())
    assertTrue(ok, "tinker's kit camp action should repair a notched item")
    assertEqual(result, "repaired", "repair action should report repaired")
    assertEqual(sword.notches, 0, "tinker's kit should remove one notch")

    local destroyedShield = inventory.createItem({
        name = "Destroyed Shield",
        size = 1,
        durability = 1,
    })
    destroyedShield.notches = 1
    destroyedShield.destroyed = true
    ok, result = camp_actions.resolveRepair(actor, destroyedShield, events.createEventBus())
    assertTrue(not ok, "tinker's kit should not salvage destroyed equipment")
    assertEqual(destroyedShield.notches, 1, "failed repair should leave destroyed item notches unchanged")
    assertTrue(destroyedShield.destroyed, "failed repair should leave destroyed item destroyed")
end

local function checkCampFletchArrowsAction()
    local actor = base_entity.createEntity({
        id = "pc_fletcher",
        name = "Fletcher",
        isPC = true,
    })
    actor.inventory = inventory.createInventory()
    actor.inventory:addItem(inventory.createItemFromTemplate("bow"), inventory.LOCATIONS.PACK)
    actor.ammo = 2

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawFletch = false
    for _, action in ipairs(available) do
        if action.id == "fletch_arrows" then
            sawFletch = true
            break
        end
    end
    assertTrue(sawFletch, "Fletch Arrows should be available to a PC carrying a missile weapon")

    local ok, result = camp_actions.resolveFletchArrows(actor, events.createEventBus())
    assertTrue(ok, "Fletch Arrows should resolve for a missile-weapon user")
    assertEqual(result, "ammo_refilled", "Fletch Arrows should report ammo refill")
    assertEqual(actor.ammo, 12, "Fletch Arrows should refill ammunition to twelve")

    actor.ammo = 14
    ok = camp_actions.resolveFletchArrows(actor, events.createEventBus())
    assertTrue(ok, "Fletch Arrows should allow already-full quivers")
    assertEqual(actor.ammo, 14, "Fletch Arrows should not reduce ammo above twelve")

    local noBow = base_entity.createEntity({
        id = "pc_no_missile_weapon",
        name = "No Missile Weapon",
        isPC = true,
    })
    noBow.inventory = inventory.createInventory()
    ok, result = camp_actions.resolveFletchArrows(noBow, events.createEventBus())
    assertTrue(not ok, "Fletch Arrows should require a bow or crossbow")
    assertEqual(result, "Requires a bow or crossbow", "missing missile weapon should explain Fletch failure")
end

local function checkCampFellowshipAction()
    local actor = base_entity.createEntity({
        id = "pc_fellowship_actor",
        name = "Fellowship Actor",
        isPC = true,
    })
    local target = base_entity.createEntity({
        id = "pc_fellowship_target",
        name = "Fellowship Target",
        isPC = true,
    })

    local available = camp_actions.getAvailableActions(actor, { actor })
    local sawFellowship = false
    for _, action in ipairs(available) do
        if action.id == "fellowship" then
            sawFellowship = true
            break
        end
    end
    assertTrue(not sawFellowship, "Fellowship should require another adventurer")

    available = camp_actions.getAvailableActions(actor, { actor, target })
    sawFellowship = false
    for _, action in ipairs(available) do
        if action.id == "fellowship" then
            sawFellowship = true
            break
        end
    end
    assertTrue(sawFellowship, "Fellowship should be available with another adventurer")

    local ok, result = camp_actions.resolveFellowship(actor, actor, events.createEventBus())
    assertTrue(not ok, "Fellowship should not target yourself")
    assertEqual(result, "Cannot fellowship with yourself", "self-fellowship should explain failure")

    ok, result = camp_actions.resolveFellowship(actor, target, events.createEventBus())
    assertTrue(ok, "Fellowship should resolve with another adventurer")
    assertEqual(result, "fellowship_complete", "Fellowship should report completion")
    assertTrue(actor.bonds[target.id].charged, "Fellowship should charge actor's bond with target")
    assertTrue(target.bonds[actor.id].charged, "Fellowship should charge target's bond with actor")
end

local function checkCampTrainAction()
    local trainee = base_entity.createEntity({
        id = "pc_train_trainee",
        name = "Train Trainee",
        isPC = true,
    })
    trainee.xp = 3
    trainee.path = "pentacles"
    trainee.talents = {}

    local trainer = base_entity.createEntity({
        id = "pc_train_trainer",
        name = "Train Trainer",
        isPC = true,
        talents = {
            war_stories = { mastered = true },
        },
    })

    local available = camp_actions.getAvailableActions(trainee, { trainee, trainer })
    local sawTrain = false
    for _, action in ipairs(available) do
        if action.id == "train" and action.name == "Train" then
            sawTrain = true
            break
        end
    end
    assertTrue(sawTrain, "Train should be available with another adventurer")

    local controller = camp_controller.createCampController({
        eventBus = events.createEventBus(),
        guild = { trainee, trainer },
    })
    controller:transitionTo(camp_controller.STATES.ACTIONS)

    local ok, result = controller:submitAction(trainee, {
        type = "train",
        target = trainer,
        talentId = "war_stories",
        xp = 2,
    })
    assertTrue(ok, "Train should resolve with a mastered trainer talent and enough XP")
    assertEqual(result, "training_complete", "Train should report completion")
    assertEqual(trainee.xp, 1, "Train should spend invested XP")
    assertTrue(trainee.talents.war_stories ~= nil, "Train should create the mentored talent")
    assertTrue(trainee.talents.war_stories.mentored, "cross-path Train should mark the talent as mentored")
    assertTrue(not trainee.talents.war_stories.mastered, "two invested XP should not master the talent")
    assertEqual(trainee.talents.war_stories.xp_invested, 2, "Train should record invested XP")
    assertEqual(trainee.talents.war_stories.uses_remaining, 2, "Train should prepare uses equal to XP invested")
    assertTrue(controller.actionsCompleted[trainer.id] ~= nil, "Train should consume the trainer's Camp Action")
    assertTrue(controller:canAdvanceFromActions(), "Train should count as both adventurers' Camp Actions")

    ok, result = controller:submitAction(trainer, { type = "rest" })
    assertTrue(not ok, "trainer should not take a second Camp Action after training")
    assertEqual(result, "Action already taken", "spent trainer action should explain duplicate action failure")

    local poorTrainee = base_entity.createEntity({
        id = "pc_poor_trainee",
        name = "Poor Trainee",
        isPC = true,
    })
    poorTrainee.xp = 0
    poorTrainee.talents = {}
    ok, result = camp_actions.resolveTrain(poorTrainee, trainer, {
        talentId = "war_stories",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should require XP to invest")
    assertEqual(result, "Not enough XP", "missing XP should explain Train failure")

    local kinTeacher = base_entity.createEntity({
        id = "pc_kin_train_teacher",
        name = "Kin Train Teacher",
        isPC = true,
        talents = {
            proud_and_ancient = { mastered = true },
        },
    })
    local kinStudent = base_entity.createEntity({
        id = "pc_kin_train_student",
        name = "Kin Train Student",
        isPC = true,
    })
    kinStudent.path = "swords"
    kinStudent.kin = "human"
    kinStudent.xp = 3
    kinStudent.talents = {}
    ok, result = camp_actions.resolveTrain(kinStudent, kinTeacher, {
        talentId = "proud_and_ancient",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(not ok, "Train should reject kin talents")
    assertEqual(result, "Kin talents cannot be trained", "kin talent training should explain the rulebook restriction")
    assertEqual(kinStudent.xp, 3, "rejected kin talent training should not spend XP")
    assertTrue(kinStudent.talents.proud_and_ancient == nil, "rejected kin talent training should not create the talent")

    local pathStudent = base_entity.createEntity({
        id = "pc_path_train_student",
        name = "Path Train Student",
        isPC = true,
    })
    pathStudent.path = "swords"
    pathStudent.xp = 1
    pathStudent.talents = {}
    local pathTeacher = base_entity.createEntity({
        id = "pc_path_train_teacher",
        name = "Path Train Teacher",
        isPC = true,
        talents = {
            aegis = { mastered = true },
        },
    })
    ok, result = camp_actions.resolveTrain(pathStudent, pathTeacher, {
        talentId = "aegis",
        xp = 1,
    }, {}, events.createEventBus())
    assertTrue(ok, "Train should allow an adventurer to invest in their own path talent")
    assertTrue(pathStudent.talents.aegis.pathTrained, "own-path Train should record path training")
    assertTrue(not pathStudent.talents.aegis.mentored, "own-path Train should not mark the talent as mentored")

    trainee.xp = 5
    ok, result = camp_actions.resolveTrain(trainee, trainer, {
        talentId = "war_stories",
        xp = 5,
    }, {}, events.createEventBus())
    assertTrue(ok, "additional training should resolve")
    assertTrue(trainee.talents.war_stories.mastered, "seven total invested XP should master the talent")
end

local function checkCampUseTalentAction()
    local beastMaster = base_entity.createEntity({
        id = "pc_camp_beast_master",
        name = "Camp Beast Master",
        isPC = true,
        talents = {
            beast_master = { mastered = true },
        },
    })
    local hound = {
        id = "hound_camp",
        name = "Camp Hound",
        knownCommands = { "Fetch", "Stay" },
        conditions = {},
    }
    beastMaster.animalCompanions = { hound }

    local available = camp_actions.getAvailableActions(beastMaster, { beastMaster })
    local sawUseTalent = false
    for _, action in ipairs(available) do
        if action.id == "use_talent" and action.name == "Use a Talent" then
            sawUseTalent = true
            break
        end
    end
    assertTrue(sawUseTalent, "Use a Talent should be available for usable Camp talents")

    local ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Guard",
    }, {}, events.createEventBus())
    assertTrue(ok, "Beast Master camp talent should teach a command")
    assertEqual(result, "companion_command_taught", "Beast Master should report command teaching")
    assertTrue(hasValue(hound.knownCommands, "Guard"), "Beast Master should add the taught command")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Track",
    }, {}, events.createEventBus())
    assertTrue(not ok, "ordinary animal companions should cap at three commands")
    assertEqual(result, "Companion already knows three commands", "command cap should explain Beast Master failure")

    ok, result = camp_actions.resolveUseTalent(beastMaster, {
        talentId = "beast_master",
        companionId = "hound_camp",
        command = "Track",
        replaceCommand = "Stay",
    }, {}, events.createEventBus())
    assertTrue(ok, "Beast Master should retrain a known command")
    assertTrue(hasValue(hound.knownCommands, "Track"), "replacement command should be learned")
    assertTrue(not hasValue(hound.knownCommands, "Stay"), "replaced command should be removed")

    local storyteller = base_entity.createEntity({
        id = "pc_war_stories",
        name = "Storyteller",
        isPC = true,
        talents = {
            war_stories = { mastered = true },
        },
    })
    storyteller.resolve = { current = 4, max = 4 }
    local listener = base_entity.createEntity({
        id = "pc_story_listener",
        name = "Story Listener",
        isPC = true,
    })
    listener.bonds = {
        pc_war_stories = { charged = false },
    }
    ok, result = camp_actions.resolveUseTalent(storyteller, {
        talentId = "war_stories",
        participants = { storyteller, listener },
        benefits = {
            pc_war_stories = { type = "resolve" },
            pc_story_listener = { type = "charge_bond", bondTargetId = "pc_war_stories" },
        },
    }, {}, events.createEventBus())
    assertTrue(ok, "War Stories should resolve as a Camp talent")
    assertEqual(result, "war_stories_shared", "War Stories should report shared story")
    assertEqual(storyteller.resolve.current, 5, "War Stories should raise Resolve to five")
    assertEqual(storyteller.resolve.max, 5, "War Stories should allow Resolve maximum five")
    assertTrue(listener.bonds.pc_war_stories.charged, "War Stories should charge selected uncharged Bonds")

    local chantEvent = nil
    local chantBus = events.createEventBus()
    chantBus:on("camp_action_resolved", function(data)
        if data.talentId == "high_chant" then
            chantEvent = data
        end
    end)
    local chanter = base_entity.createEntity({
        id = "pc_high_chant",
        name = "High Chant",
        isPC = true,
        cups = 2,
        talents = {
            high_chant = { mastered = true },
        },
    })
    local chantAlly = base_entity.createEntity({
        id = "pc_high_chant_ally",
        name = "High Chant Ally",
        isPC = true,
    })
    local chantSword = { name = "Three of Swords", value = 3, suit = constants.SUITS.SWORDS }
    local chantCups = { name = "Four of Cups", value = 4, suit = constants.SUITS.CUPS }
    local chantWands = { name = "Five of Wands", value = 5, suit = constants.SUITS.WANDS }
    local discardPile = { chantSword, chantCups, chantWands }
    local detail = nil
    ok, result, detail = camp_actions.resolveUseTalent(chanter, {
        talentId = "high_chant",
        cards = { chantSword, chantCups },
        recipients = { chanter, chantAlly },
        discardPile = discardPile,
    }, {
        guild = { chanter, chantAlly },
    }, chantBus)
    assertTrue(ok, "High Chant should resolve as a Camp talent")
    assertEqual(result, "high_chant_performed", "High Chant should report performance")
    assertEqual(#detail, 2, "High Chant should grant up to Cups inspiration cards")
    assertEqual(#discardPile, 1, "High Chant should remove selected cards from the minor discard pile")
    assertEqual(discardPile[1], chantWands, "High Chant should leave unselected discard cards")
    assertEqual(chanter.inspirationCard, chantSword, "High Chant performer may keep one inspiration card")
    assertEqual(chantAlly.inspirationCard, chantCups, "High Chant should distribute inspiration to another player")
    assertEqual(chantCups.inspiration.source, "high_chant", "High Chant cards should carry inspiration metadata")
    assertEqual(chantCups.inspiration.expires, "session_end", "High Chant inspiration should last until session end")
    assertTrue(chantEvent and #chantEvent.inspirationCards == 2, "High Chant should emit granted cards")

    local spentEvent = nil
    local spentBus = events.createEventBus()
    spentBus:on("inspiration_card_spent", function(data)
        spentEvent = data
    end)
    local inspirationDiscard = {
        discarded = {},
        discard = function(self, card)
            self.discarded[#self.discarded + 1] = card
        end,
    }
    chanter.zone = "A"
    chanter.pentacles = 7
    local inspiredResolver = action_resolver.createActionResolver({
        eventBus = spentBus,
        playerDeck = inspirationDiscard,
    })
    local inspiredAction = inspiredResolver:resolve({
        actor = chanter,
        card = chantSword,
        type = action_resolver.ACTION_TYPES.DASH,
        destinationZone = "B",
    })
    assertTrue(inspiredAction.success, "inspiration cards should be usable as Challenge action cards")
    assertTrue(hasValue(inspiredAction.effects, "inspiration_spent"),
        "using an inspiration action card should report the spend")
    assertTrue(chanter.inspirationCard == nil, "spent inspiration action card should clear from actor")
    assertTrue(chantSword.inspiration.spent, "spent inspiration action card should be marked spent")
    assertEqual(inspirationDiscard.discarded[1], chantSword, "spent inspiration action card should be discarded")
    assertEqual(spentEvent and spentEvent.card, chantSword, "spent inspiration action card should emit an event")

    local tooMany = base_entity.createEntity({
        id = "pc_high_chant_too_many",
        name = "High Chant Too Many",
        isPC = true,
        cups = 1,
        talents = {
            high_chant = { mastered = true },
        },
    })
    local excessDiscard = {
        { name = "Six of Cups", value = 6, suit = constants.SUITS.CUPS },
        { name = "Seven of Cups", value = 7, suit = constants.SUITS.CUPS },
    }
    ok, result = camp_actions.resolveUseTalent(tooMany, {
        talentId = "high_chant",
        cards = excessDiscard,
        recipients = { tooMany, chanter },
        discardPile = excessDiscard,
    }, {}, events.createEventBus())
    assertTrue(not ok, "High Chant should not select more cards than Cups")
    assertEqual(result, "Too many inspiration cards", "High Chant Cups limit should explain failure")
    assertEqual(#excessDiscard, 2, "failed High Chant should not remove discard cards")

    local blockedCard = { name = "Eight of Cups", value = 8, suit = constants.SUITS.CUPS }
    local blockedDiscard = { blockedCard }
    ok, result = camp_actions.resolveUseTalent(chanter, {
        talentId = "high_chant",
        cards = { blockedCard },
        recipients = { chantAlly },
        discardPile = blockedDiscard,
    }, {}, events.createEventBus())
    assertTrue(not ok, "High Chant should not give a second inspiration card to one recipient")
    assertEqual(result, "Recipient already has inspiration", "High Chant inspiration cap should explain failure")
    assertEqual(blockedDiscard[1], blockedCard, "failed High Chant recipient cap should leave discard intact")

    ok, detail = inspiredResolver:spendInspirationCard(chantAlly, chantCups, {
        usage = "test_fate",
        deck = inspirationDiscard,
    })
    assertTrue(ok, "inspiration cards should be spendable for Test or Push fate hooks")
    assertTrue(chantAlly.inspirationCard == nil, "spent Test inspiration should clear from actor")
    assertEqual(chantCups.inspiration.spentFor, "test_fate", "inspiration spend helper should record usage")

    local bookworm = base_entity.createEntity({
        id = "pc_bookworm",
        name = "Bookworm",
