        id = "sturdy_chest",
        name = "Sturdy Chest",
        zone = "hall",
        properties = {},
    }
    local thunderDiscarded = {}
    local thunderDiscardDeck = {
        discard = function(_, card)
            thunderDiscarded[#thunderDiscarded + 1] = card
        end,
    }
