    shrouded.inventory:addItem(shroudBow, inventory.LOCATIONS.HANDS)
    shrouded.ammo = 1

    local cast = resolver:resolve({
        actor = caster,
        card = { name = "Wands", value = 8, suit = constants.SUITS.WANDS },
        type = action_resolver.ACTION_TYPES.SPEAK_INCANTATION,
